import { useState, useEffect } from 'react';
import { useNavigate, Link, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/admin') setActiveTab('dashboard');
    else if (path === '/admin/students') setActiveTab('students');
    else if (path === '/admin/courses') setActiveTab('courses');
    else if (path === '/admin/questions') setActiveTab('questions');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const menu = [
    { id: 'dashboard', label: 'Home', icon: 'fa-home', path: '/admin' },
    { id: 'students', label: 'Students', icon: 'fa-users', path: '/admin/students' },
    { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
    { id: 'questions', label: 'Questions', icon: 'fa-question-circle', path: '/admin/questions' }
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: '#eef2f7' }}>

      {/* SIDEBAR */}
      <aside style={{
        width: '250px',
        background: 'linear-gradient(180deg, #0f172a, #1e293b)',
        color: '#cbd5f5',
        paddingTop: '20px',
        boxShadow: '4px 0 25px rgba(0,0,0,0.3)'
      }}>
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <img src="/logo.png" style={{ width: '80px', borderRadius: '50%' }} />
          <h6 style={{ marginTop: '10px', color: '#fff' }}>Admin Panel</h6>
        </div>

        {menu.map(item => (
          <Link
            key={item.id}
            to={item.path}
            onClick={() => setActiveTab(item.id)}
            style={{
              display: 'flex',
              alignItems: 'center',
              padding: '14px 20px',
              fontSize: '15px',
              color: activeTab === item.id ? '#fff' : '#94a3b8',
              background: activeTab === item.id ? 'rgba(59,130,246,0.15)' : 'transparent',
              borderLeft: activeTab === item.id ? '4px solid #3b82f6' : '4px solid transparent',
              textDecoration: 'none',
              transition: '0.2s'
            }}
          >
            <i className={`fas ${item.icon}`} style={{ marginRight: '12px' }}></i>
            {item.label}
          </Link>
        ))}
      </aside>

      {/* MAIN */}
      <main style={{ flex: 1, padding: '25px' }}>

        {/* HEADER */}
        <div style={{
          background: 'linear-gradient(90deg, #3b82f6, #06b6d4)',
          borderRadius: '12px',
          padding: '20px 25px',
          marginBottom: '25px',
          color: '#fff',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          boxShadow: '0 10px 30px rgba(0,0,0,0.2)'
        }}>
          <div>
            <h4 style={{ margin: 0 }}>Admin Dashboard</h4>
            <small>Manage your Online Quiz Platform</small>
          </div>

          <button
            onClick={handleLogout}
            style={{
              background: '#ef4444',
              border: 'none',
              padding: '8px 14px',
              borderRadius: '8px',
              color: '#fff'
            }}
          >
            Logout
          </button>
        </div>

        {/* CONTENT */}
        <div style={{
          background: '#ffffff',
          borderRadius: '12px',
          padding: '25px',
          boxShadow: '0 8px 30px rgba(0,0,0,0.08)'
        }}>
          <Routes>
            <Route index element={<Home />} />
            <Route path="students" element={<Students />} />
            <Route path="courses" element={<Courses />} />
            <Route path="questions" element={<Questions />} />
          </Routes>
        </div>

      </main>
    </div>
  );
}
